    describe('AssignSubflowOutputs - Placement Validation', () => {
        test('should error when used in Flow (not Subflow)', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'assign-outputs-in-flow.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa } from '@servicenow/sdk/automation'
import { StringColumn } from '@servicenow/sdk/core'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    undefined,
    (params) => {
        // Invalid: AssignSubflowOutputs in Flow (not Subflow)
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['assign'] },
            {} as any,
            { result: 'success' }
        )
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find(
                (d) => d.message === 'AssignSubflowOutputs can only be used within a SubflowDefinition or Subflow'
            )
            expect(error).toBeDefined()
            expect(error?.level).toBe(Diagnostic.Level.Error)
        })

        test('should NOT error when used in Subflow', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'assign-outputs-in-subflow-def.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Subflow, wfa } from '@servicenow/sdk/automation'
import { StringColumn } from '@servicenow/sdk/core'

Subflow(
    {
        $id: Now.ID['test_subflow'],
        name: 'Test Subflow',
        inputs: {
            input1: StringColumn({ label: 'Input 1' })
        },
        outputs: {
            result: StringColumn({ label: 'Result' })
        }
    },
    (params) => {
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['assign'] },
            params.outputs,
            { result: 'success' }
        )
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find((d) => d.message.includes('can only be used within'))
            expect(error).toBeUndefined()
        })
    })

    describe('AssignSubflowOutputs - Values Validation', () => {
        test('should error when values object is empty', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'assign-outputs-empty-values.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Subflow, wfa } from '@servicenow/sdk/automation'
import { StringColumn } from '@servicenow/sdk/core'

Subflow(
    {
        $id: Now.ID['test_subflow'],
        name: 'Test Subflow',
        outputs: {
            result: StringColumn({ label: 'Result' })
        }
    },
    (params) => {
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['assign'] },
            params.outputs,
            {}  // Empty values object
        )
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find((d) => d.message.includes('Values object cannot be empty'))
            expect(error).toBeDefined()
            expect(error?.level).toBe(Diagnostic.Level.Error)
        })

        test('should error when output value has invalid type', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'assign-outputs-invalid-value-type.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Subflow, wfa } from '@servicenow/sdk/automation'
import { StringColumn } from '@servicenow/sdk/core'

Subflow(
    {
        $id: Now.ID['test_subflow'],
        name: 'Test Subflow',
        outputs: {
            result: StringColumn({ label: 'Result' })
        }
    },
    (params) => {
        const localVar = 'test'  // Local variable
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['assign'] },
            params.outputs,
            {
                result: localVar as any  // Invalid: identifier/local variable
            }
        )
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find((d) => d.message.includes('cannot use local variable references'))
            expect(error).toBeDefined()
            expect(error?.level).toBe(Diagnostic.Level.Error)
        })

        test('should accept valid value types', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'assign-outputs-valid-types.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Subflow, wfa, ActionDefinition } from '@servicenow/sdk/automation'
import { StringColumn, IntegerColumn, BooleanColumn } from '@servicenow/sdk/core'

const testAction = ActionDefinition({
    $id: Now.ID['test_action'],
    name: 'Test Action',
    inputs: {
        input1: StringColumn({ label: 'Input 1' })
    },
    outputs: {
        output1: StringColumn({ label: 'Output 1' })
    }
})

Subflow(
    {
        $id: Now.ID['test_subflow'],
        name: 'Test Subflow',
        inputs: {
            input1: StringColumn({ label: 'Input 1' })
        },
        outputs: {
            strOut: StringColumn({ label: 'String Out' }),
            numOut: IntegerColumn({ label: 'Number Out' }),
            boolOut: BooleanColumn({ label: 'Bool Out' }),
            actionOut: StringColumn({ label: 'Action Out' })
        }
    },
    (params) => {
        const actionResult = wfa.action(
            testAction,
            { $id: Now.ID['action_instance'] },
            { input1: params.inputs.input1 }
        )

        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['assign'] },
            params.outputs,
            {
                strOut: 'hello',  // String literal
                numOut: 42,  // Number literal
                boolOut: true,  // Boolean literal
                actionOut: actionResult.output1  // Datapill from action
            }
        )
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find((d) => d.message.includes('has invalid value type'))
            expect(error).toBeUndefined()
        })
    })

